insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-03','nieuw','Documenten','Alle datums van het dossier in je documenten',
   'In een Word-sjabloon kun je nu elke datum van het dossier gebruiken: aanvraag-, offerte-, opdracht-, start-, eind-, oplever- en financieel-gereed-datum en de deadline. Per datum is er ook een schakelaar, zodat een regel helemaal wegvalt als die datum nog niet bekend is in plaats van leeg af te drukken. Je vindt ze in de sjabloon-editor onder "Datums van het dossier".'),

  ('2026-09-03','opgelost','Dossiers','Blokken op de Informatie-tab stonden alsnog ongelijk',
   'Het Acties-blok rekte met veel openstaande acties de hele rij op, waardoor er een groot wit gat onder Projectinformatie ontstond en de blokken niet gelijk eindigden. Acties, Notities en Klantchat doen nu mee aan dezelfde vaste hoogte, en elk blok vult zijn rij helemaal.');
